"""Package a self-contained Three.js preview; no network dependencies."""
from pathlib import Path
import base64
root=Path(__file__).resolve().parent.parent
out=root/'dog-model-preview'
three=(root/'vendor/three/three.min.js').read_text()
model=base64.b64encode((out/'resting-dog.glb').read_bytes()).decode()
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resting dog — 3D preview</title>
<style>*{box-sizing:border-box}body{margin:0;background:#14171c;color:#e7ded0;font:15px Georgia,serif;overflow:hidden}canvas{display:block;touch-action:none}header{position:absolute;left:28px;top:24px;pointer-events:none}h1{font-weight:normal;font-size:24px;margin:0 0 8px}.eyebrow{font:10px system-ui;letter-spacing:3px;color:#ad9d85;margin-bottom:12px}header p{color:#a7a29b;margin:0;font-size:13px}footer{position:absolute;bottom:25px;left:0;right:0;text-align:center}button{background:#23262bcf;color:#e7ded0;border:1px solid #635746;padding:10px 16px;border-radius:22px;margin:4px;cursor:pointer;font:13px Georgia}button[aria-pressed=true]{background:#756149;color:#fff}#status{position:absolute;left:0;right:0;top:45%;text-align:center;color:#b9ae9e}.hint{font:11px system-ui;color:#9c9892;margin-top:12px}@media(max-width:600px){header{left:18px;top:18px}h1{font-size:21px}footer{bottom:16px}}</style>
<header><div class="eyebrow">REFERENCE MODEL · 06</div><h1>A dog at rest</h1><p>Smaller crown · shorter snout · dog only</p></header><div id="status">Preparing the model…</div><footer><button id="rotate" aria-pressed="false">Rotate</button><button id="breath" aria-pressed="true">Breathing</button><button id="reset">Reset view</button><div class="hint">Drag to look around · scroll or pinch to zoom</div></footer>
<script>__THREE__</script><script>
'use strict';
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputEncoding=THREE.sRGBEncoding;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.16;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;document.body.prepend(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color('#14171c');scene.fog=new THREE.Fog('#14171c',9,22);const camera=new THREE.PerspectiveCamera(37,innerWidth/innerHeight,.01,80);
scene.add(new THREE.HemisphereLight(0xc5daef,0x4e3521,.85));const key=new THREE.DirectionalLight(0xffdfbd,2.5);key.position.set(-2,5,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-3;key.shadow.camera.right=3;key.shadow.camera.top=3;key.shadow.camera.bottom=-3;key.shadow.bias=-.00015;scene.add(key);const fill=new THREE.DirectionalLight(0x8eafff,1);fill.position.set(3,3,2);scene.add(fill);const rim=new THREE.DirectionalLight(0xffd7a7,1.8);rim.position.set(1,3,-3);scene.add(rim);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0x171b20,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.002;ground.receiveShadow=true;scene.add(ground);
const encoded='__MODEL__';const raw=atob(encoded);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const buffer=bytes.buffer;const dv=new DataView(buffer);let off=12,g,bin;
while(off<buffer.byteLength){const len=dv.getUint32(off,true),type=dv.getUint32(off+4,true);if(type===0x4e4f534a)g=JSON.parse(new TextDecoder().decode(new Uint8Array(buffer,off+8,len)));if(type===0x004e4942)bin=buffer.slice(off+8,off+8+len);off+=8+len;}
const sizes={SCALAR:1,VEC2:2,VEC3:3,VEC4:4,MAT4:16};const types={5120:Int8Array,5121:Uint8Array,5122:Int16Array,5123:Uint16Array,5125:Uint32Array,5126:Float32Array};
function attribute(i){const a=g.accessors[i],v=g.bufferViews[a.bufferView],T=types[a.componentType],size=sizes[a.type],start=(v.byteOffset||0)+(a.byteOffset||0),stride=v.byteStride||size*T.BYTES_PER_ELEMENT;if(stride===size*T.BYTES_PER_ELEMENT)return new THREE.BufferAttribute(new T(bin,start,a.count*size),size,!!a.normalized);const vals=new T(a.count*size);for(let j=0;j<a.count;j++)vals.set(new T(bin,start+j*stride,size),j*size);return new THREE.BufferAttribute(vals,size,!!a.normalized);}
const materials=(g.materials||[]).map(m=>{const p=m.pbrMetallicRoughness||{},c=p.baseColorFactor||[1,1,1,1];return new THREE.MeshStandardMaterial({color:new THREE.Color(c[0],c[1],c[2]),opacity:c[3],transparent:m.alphaMode==='BLEND',roughness:p.roughnessFactor??1,metalness:p.metallicFactor??0,side:m.doubleSided?THREE.DoubleSide:THREE.FrontSide});});
const nodes=g.nodes.map((n,i)=>{let ob=new THREE.Group();ob.name=n.name||String(i);if(n.mesh!==undefined)for(const p of g.meshes[n.mesh].primitives){const geo=new THREE.BufferGeometry();for(const [k,v]of Object.entries(p.attributes)){const name={POSITION:'position',NORMAL:'normal',TEXCOORD_0:'uv',COLOR_0:'color'}[k];if(name)geo.setAttribute(name,attribute(v));}if(p.indices!==undefined)geo.setIndex(attribute(p.indices));const mat=(materials[p.material]||new THREE.MeshStandardMaterial()).clone();mat.vertexColors=!!geo.attributes.color;const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=!n.name.includes('fur');mesh.receiveShadow=true;ob.add(mesh);}if(n.matrix){ob.matrix.fromArray(n.matrix);ob.matrix.decompose(ob.position,ob.quaternion,ob.scale);}else{if(n.translation)ob.position.fromArray(n.translation);if(n.rotation)ob.quaternion.fromArray(n.rotation);if(n.scale)ob.scale.fromArray(n.scale);}return ob;});
g.nodes.forEach((n,i)=>(n.children||[]).forEach(c=>nodes[i].add(nodes[c])));const asset=new THREE.Group();for(const i of g.scenes[g.scene||0].nodes)asset.add(nodes[i]);scene.add(asset);
const dogName='Resting dog · reference model v1';const sofaNodes=nodes.filter((ob,i)=>!ob.parent||ob.parent===asset).filter(ob=>ob.name!==dogName);const animations=[];let duration=0;
for(const a of g.animations||[])for(const c of a.channels){if(!['translation','scale','rotation'].includes(c.target.path))continue;const s=a.samplers[c.sampler],times=attribute(s.input).array,values=attribute(s.output).array;duration=Math.max(duration,times[times.length-1]);animations.push({object:nodes[c.target.node],path:c.target.path,times,values,size:c.target.path==='rotation'?4:3});}
let az=-.30,el=.33,dist=2.45,target=new THREE.Vector3(-.10,.24,0),rotating=false,breathing=true,showSofa=false,pointer=null;function reset(){az=-.30;el=.33;dist=2.45;target.set(-.10,.24,0);}function updateCamera(){camera.position.set(target.x+dist*Math.sin(az)*Math.cos(el),target.y+dist*Math.sin(el),target.z+dist*Math.cos(az)*Math.cos(el));camera.lookAt(target);}
const canvas=renderer.domElement;canvas.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!pointer)return;az-=(e.clientX-pointer.x)*.006;el=Math.max(-.05,Math.min(1.35,el+(e.clientY-pointer.y)*.005));pointer={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',()=>pointer=null);canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('wheel',e=>{e.preventDefault();dist=Math.max(1.1,Math.min(9,dist*Math.exp(e.deltaY*.001)));},{passive:false});
document.querySelector('#rotate').onclick=e=>{rotating=!rotating;e.target.setAttribute('aria-pressed',rotating);};document.querySelector('#breath').onclick=e=>{breathing=!breathing;e.target.setAttribute('aria-pressed',breathing);};document.querySelector('#reset').onclick=reset;
addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});document.querySelector('#status').remove();let last=0,clock=0;function draw(now){requestAnimationFrame(draw);const dt=Math.min(.06,(now-last)/1000);last=now;if(rotating&&!pointer)az+=dt*.12;if(breathing)clock+=dt;const t=duration?clock%duration:0;for(const a of animations){let j=0;while(j<a.times.length-2&&a.times[j+1]<t)j++;const j2=Math.min(j+1,a.times.length-1),f=Math.max(0,Math.min(1,(t-a.times[j])/(a.times[j2]-a.times[j]||1))),ar=[];for(let k=0;k<a.size;k++)ar.push(a.values[j*a.size+k]*(1-f)+a.values[j2*a.size+k]*f);if(a.path==='scale')a.object.scale.fromArray(ar);if(a.path==='translation')a.object.position.fromArray(ar);if(a.path==='rotation')a.object.quaternion.fromArray(ar).normalize();}updateCamera();renderer.render(scene,camera);}requestAnimationFrame(draw);window.dogPreview={scene,asset,g,nodes,renderer};
</script></html>'''
html=html.replace('__THREE__',three).replace('__MODEL__',model)
(out/'resting-dog-preview.html').write_text(html)
print(out/'resting-dog-preview.html')
